CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultSecurityAsset_AfterDelete] ON [dbo].[ResponsibilityRuleResultSecurityAsset] AFTER DELETE AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted R INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on R.RuleID = RA.RuleID INNER JOIN [dbo].[Asset] A ON RA.AssetID = A.ID WHERE RA.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM deleted R INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on R.RuleID = RA.RuleID INNER JOIN [dbo].[Asset] A ON RA.AssetTypeID = A.AssetTypeID WHERE RA.AssetID = 0; END

CREATE OR ALTER TRIGGER [dbo].[ResponsibilityRuleResultSecurityAsset_AfterInsert] ON [dbo].[ResponsibilityRuleResultSecurityAsset] AFTER INSERT AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM INSERTED R INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on R.RuleID = RA.RuleID INNER JOIN [dbo].[Asset] A ON RA.AssetID = A.ID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] RTR ON R.RuleID = RTR.ID WHERE RTR.LastRunOn IS NOT NULL AND RA.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM INSERTED R INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on R.RuleID = RA.RuleID INNER JOIN [dbo].[Asset] A ON RA.AssetTypeID = A.AssetTypeID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] RTR ON R.RuleID = RTR.ID WHERE RTR.LastRunOn IS NOT NULL AND RA.AssetID = 0; END
